<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigRecoverPassEmailAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigRecoverPassEmailAccessor trait.
 *
 * Covers null default, string/VO assignment via withRecoverPassEmail,
 * getRecoverPassEmail/recoverPassEmail accessors, and isRecoverPassEmailChanged with/without original.
 */
class TenantConfigRecoverPassEmailAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRecoverPassEmail creates a new instance with the RecoverPassEmail set
     * from a string value, and getRecoverPassEmail returns the primitive string.
     */
    public function testWithRecoverPassEmailFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRecoverPassEmailAccessorUnitTest();

        // Act
        $result = $holder->withRecoverPassEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getRecoverPassEmail());
    }
    /**
     * Asserts that withrecoverPassEmail has access to the value object
     * from a string value, and getRecoverPassEmail returns the primitive string.
     */
    public function testWithRecoverPassEmailFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRecoverPassEmailAccessorUnitTest();

        // Act
        $result = $holder->withRecoverPassEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->recoverPassEmail()->value());
    }
    public function testChangedRecoverPassEmail(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRecoverPassEmailAccessorUnitTest();
        $original = $holder->withRecoverPassEmail( 'one');
        $same = $holder->withRecoverPassEmail( 'one');
        $modified = $holder->withRecoverPassEmail('other');

        // Act
        $unchanged = $holder->isRecoverPassEmailChanged();
        $withSame = $original->isRecoverPassEmailChanged( $same );
        $withDiferent = $original->isRecoverPassEmailChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigRecoverPassEmailAccessorUnitTest
{
  use TenantConfigRecoverPassEmailAccessor;
}
